const eventDayKey=(value?:string)=>{if(!value)return ''; const timestamp=Date.parse(value); if(Number.isNaN(timestamp))return value.slice(0,10); const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(timestamp)); const pick=(type:string)=>parts.find(part=>part.type===type)?.value||''; return `${pick('year')}-${pick('month')}-${pick('day')}`};
const shiftDateKey=(dateKey:string,offset:number)=>{if(!dateKey)return ''; const date=new Date(`${dateKey}T00:00:00Z`); if(Number.isNaN(date.getTime()))return ''; date.setUTCDate(date.getUTCDate()+offset); return date.toISOString().slice(0,10)};
