const formatCandleDate=(iso:string|undefined,interval:CandleInterval|string='daily')=>{if(!iso)return '—'; const date=new Date(iso); if(Number.isNaN(date.getTime()))return '—'; const options: Intl.DateTimeFormatOptions=interval==='hourly'?{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}:interval==='yearly'||interval==='weekly'?{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}:interval==='monthly'?{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}:{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}; const parts=new Intl.DateTimeFormat('zh-CN',options).formatToParts(date); const value=(type:string)=>parts.find(part=>part.type===type)?.value||''; if(interval==='hourly')return `${value('month')}-${value('day')} ${value('hour')}:${value('minute')}`; if(interval==='yearly')return value('year'); if(interval==='monthly')return `${value('year')}-${value('month')}`; if(interval==='weekly'){const localDate=new Date(Date.UTC(Number(value('year')),Number(value('month'))-1,Number(value('day')))); const day=localDate.getUTCDay()||7; localDate.setUTCDate(localDate.getUTCDate()+4-day); const yearStart=new Date(Date.UTC(localDate.getUTCFullYear(),0,1)); const week=Math.ceil((((localDate.getTime()-yearStart.getTime())/86400000)+1)/7); return `${localDate.getUTCFullYear()}-W${String(week).padStart(2,'0')}`;} return `${value('month')}-${value('day')}`};
