 const pollAccountBridge=async(signal?:AbortSignal)=>{
 const checked=validateBridgeUrl(accountBridgeUrl);
  if(!checked.ok){setAccountBridgeStatus('invalid');setAccountBridge(null);setAccountBridgeError(checked.message);setAccountBridgeFailureCount(value=>Math.min(3,value+1));return}
  setAccountBridgeStatus('connecting');setAccountBridgeError('');
  const controller=new AbortController();
  const timeout=window.setTimeout(()=>controller.abort(),2500);
  const abortForward=()=>controller.abort();
  signal?.addEventListener('abort',abortForward,{once:true});
  try{
   const response=await fetch(checked.url,{method:'GET',cache:'no-store',headers:{Accept:'application/json'},signal:controller.signal});
   const raw=await response.json().catch(()=>null);
   if(!response.ok)throw new Error(`桥接返回 HTTP ${response.status}`);
   const result=normaliseAccountBridgePayload(raw,checked.url);
   if(!result.ok){setAccountBridge(null);setAccountBridgeStatus('invalid');setAccountBridgeError(result.message);setAccountBridgeFailureCount(value=>Math.min(3,value+1));return}
   setAccountBridge(result.payload);
   const status=result.payload.status==='ok'?'ok':result.payload.status==='partial'?'partial':result.payload.status==='disconnected'?'disconnected':'invalid';
   setAccountBridgeStatus(status);
   setAccountBridgeError(result.payload.message||'');
   setAccountBridgeLastPoll(new Date().toISOString());
   setAccountBridgeFailureCount(0);
  }catch(error){
   if(error instanceof DOMException&&error.name==='AbortError')return;
   setAccountBridge(null);setAccountBridgeStatus('disconnected');setAccountBridgeError('本机桥未响应；请检查进程、CORS 与 HTTPS 设置');setAccountBridgeLastPoll(new Date().toISOString());setAccountBridgeFailureCount(value=>Math.min(3,value+1));
  }finally{window.clearTimeout(timeout);signal?.removeEventListener('abort',abortForward)}
 };
 useEffect(()=>{
  if(!accountBridgeEnabled){setAccountBridge(null);setAccountBridgeStatus('idle');setAccountBridgeError('');setAccountBridgeFailureCount(0);return}
  if(typeof window==='undefined')return;
  const controller=new AbortController();
  void pollAccountBridge(controller.signal);
  const intervalMs=Math.min(30000,5000*Math.max(1,2**Math.min(accountBridgeFailureCount,2)));
  const timer=window.setInterval(()=>{if(document.visibilityState==='visible')void pollAccountBridge(controller.signal)},intervalMs);
  return()=>{controller.abort();window.clearInterval(timer)};
 },[accountBridgeEnabled,accountBridgeUrl,accountBridgeRefreshTick,accountBridgeFailureCount]);
