 useEffect(()=>{let cancelled=false; const controller=new AbortController(); const timeout=window.setTimeout(()=>controller.abort(),10000); const apiBase=process.env.NEXT_PUBLIC_API_URL||''; queueMicrotask(()=>{if(!cancelled){setCandleStatus('loading');setCandleError('');setCandles(null);setCandleHoverIndex(null)}}); const url=`${apiBase}/api/v1/market/candles?symbol=${encodeURIComponent(currentSymbol)}&interval=${candleInterval}`; fetch(url,{cache:'no-store',signal:controller.signal}).then(r=>{if(!r.ok)throw new Error('candles');return r.json()}).then((payload:unknown)=>{if(cancelled)return; const data=payload as Partial<CandlePayload>; if(!Array.isArray(data.candles)||data.candles.length<2)throw new Error('candles empty'); setCandles(data as CandlePayload);setCandleStatus('ready')}).catch(error=>{if(!cancelled){setCandles(demoCandles(currentSymbol,candleInterval));setCandleStatus('error');setCandleError(error?.name==='AbortError'?'K线接口响应超时，已自动显示本地演示形态':'K线接口未连接，已自动显示本地演示形态')}}).finally(()=>window.clearTimeout(timeout));return()=>{cancelled=true;controller.abort();window.clearTimeout(timeout)}},[currentSymbol,candleInterval,refreshTick]);
 const candleView=useMemo<CandleView>(()=>{const rows=(candles?.candles||[]).filter(c=>[c.open,c.high,c.low,c.close].every(value=>Number.isFinite(value))).slice(-48); if(!rows.length)return {rows:[],min:0,max:1,y:()=>0,left:26,width:848,bottom:258,ticks:[]}; const min=Math.min(...rows.map(c=>c.low)); const max=Math.max(...rows.map(c=>c.high)); const span=max-min||Math.max(Math.abs(max)*.01,1); const top=20; const bottom=258; const height=bottom-top; const left=26; const width=848; const step=width/Math.max(rows.length,1); const y=(value:number)=>top+((max-value)/span)*height; const plotted:PlottedCandle[]=rows.map((c,i)=>{const x=left+step*(i+.5);const bodyTop=y(Math.max(c.open,c.close));const bodyBottom=y(Math.min(c.open,c.close));return {...c,x,w:Math.max(4,step*.56),wickTop:y(c.high),wickBottom:y(c.low),bodyTop,bodyHeight:Math.max(2,bodyBottom-bodyTop),up:c.close>=c.open}}); const tickIndexes=[...new Set([0,Math.round((rows.length-1)*.2),Math.round((rows.length-1)*.4),Math.round((rows.length-1)*.6),Math.round((rows.length-1)*.8),rows.length-1])]; const interval=(candles?.effective_interval||candles?.interval||'daily') as CandleInterval|string; const ticks=tickIndexes.map(index=>({x:plotted[index].x,label:formatCandleDate(rows[index].time,interval),key:`${rows[index].time}-${index}`})); return {rows:plotted,min,max,y,left,width,bottom,ticks};},[candles]);
 const uploadReadyCount=uploads.filter(item=>item.status==='ready'||item.status==='done').length;
