 const candleHoverDate=candleHover?`${formatCandleDate(candleHover.time,candleEffectiveInterval)} · ${formatBeijingDateTime(candleHover.time)} 北京时间`:'移动光标查看单根 K 线数据';
 const candleHoverChange=typeof candleHoverDelta==='number'?`${candleHoverDelta>=0?'+':''}${formatPrice(candleHoverDelta)}${typeof candleHoverDeltaPct==='number'?` (${candleHoverDeltaPct>=0?'+':''}${candleHoverDeltaPct.toFixed(2)}%)`:''}`:'—';
 useEffect(()=>{const actions=document.querySelector('#kline .kline-actions') as HTMLElement|null; const select=actions?.querySelector('select[aria-label="K线周期"]') as HTMLSelectElement|null; if(!actions||!select)return; select.style.display='none'; let tabs=actions.querySelector('.kline-period-tabs') as HTMLElement|null; if(!tabs){tabs=document.createElement('div');tabs.className='kline-period-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','K线周期');(['hourly','daily','weekly','monthly','yearly'] as CandleInterval[]).forEach(period=>{const button=document.createElement('button');button.type='button';button.setAttribute('role','tab');button.dataset.period=period;button.textContent=candleIntervalLabel(period);button.addEventListener('click',()=>setCandleInterval(period));tabs?.appendChild(button)});actions.insertBefore(tabs,select)} tabs.querySelectorAll('button[data-period]').forEach(node=>{const button=node as HTMLButtonElement;const active=button.dataset.period===candleInterval;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))})});
 useEffect(()=>{const chart=document.querySelector('#kline .kline-chart') as SVGSVGElement|null; const target=chart; if(!target||!candleView.rows.length)return; const indexAt=(clientX:number,clientY:number)=>{const rect=chart.getBoundingClientRect(); if(!rect.width||!rect.height)return 0; let localX=candleView.left+((clientX-rect.left)/rect.width)*900; try{const point=chart.createSVGPoint();point.x=clientX;point.y=clientY;const matrix=chart.getScreenCTM()?.inverse();if(matrix)localX=point.matrixTransform(matrix).x}catch{/* Keep the viewport-scale fallback when an SVG transform is unavailable. */} const viewX=Math.max(candleView.left,Math.min(candleView.left+candleView.width,localX)); let nearest=0; let distance=Number.POSITIVE_INFINITY; candleView.rows.forEach((row,index)=>{const next=Math.abs(row.x-viewX);if(next<distance){distance=next;nearest=index}});return nearest}; const onPointerMove=(event:globalThis.PointerEvent)=>setCandleHoverIndex(indexAt(event.clientX,event.clientY)); const onMouseMove=(event:globalThis.MouseEvent)=>setCandleHoverIndex(indexAt(event.clientX,event.clientY)); const onTouchMove=(event:globalThis.TouchEvent)=>{const touch=event.touches[0];if(touch)setCandleHoverIndex(indexAt(touch.clientX,touch.clientY))}; const clear=()=>setCandleHoverIndex(null); target.addEventListener('pointermove',onPointerMove);target.addEventListener('pointerdown',onPointerMove);target.addEventListener('mousemove',onMouseMove);target.addEventListener('mousedown',onMouseMove);target.addEventListener('touchstart',onTouchMove,{passive:true});target.addEventListener('touchmove',onTouchMove,{passive:true});target.addEventListener('pointerleave',clear);target.addEventListener('mouseleave',clear);target.addEventListener('touchend',clear,{passive:true});target.addEventListener('pointercancel',clear);return()=>{target.removeEventListener('pointermove',onPointerMove);target.removeEventListener('pointerdown',onPointerMove);target.removeEventListener('mousemove',onMouseMove);target.removeEventListener('mousedown',onMouseMove);target.removeEventListener('touchstart',onTouchMove);target.removeEventListener('touchmove',onTouchMove);target.removeEventListener('pointerleave',clear);target.removeEventListener('mouseleave',clear);target.removeEventListener('touchend',clear);target.removeEventListener('pointercancel',clear)}},[candleView]);
 useEffect(()=>{const chart=document.querySelector('#kline .kline-chart') as SVGSVGElement|null;if(!chart||!candleView.rows.length)return;const onKey=(event:KeyboardEvent)=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const last=candleView.rows.length-1;setCandleHoverIndex(current=>{const base=current===null?(event.key==='ArrowLeft'?last:0):current;if(event.key==='Home')return 0;if(event.key==='End')return last;return Math.max(0,Math.min(last,base+(event.key==='ArrowLeft'?-1:1)))})};chart.addEventListener('keydown',onKey);return()=>chart.removeEventListener('keydown',onKey)},[candleView.rows.length]);
 const candleReferencePrice=typeof candles?.reference_price==='number'&&Number.isFinite(candles.reference_price)?candles.reference_price:null;
 const mainReferencePrice=typeof activeSnapshot?.price==='number'&&Number.isFinite(activeSnapshot.price)?activeSnapshot.price:null;
 const referenceGapPct=candleReferencePrice!==null&&mainReferencePrice!==null&&mainReferencePrice!==0?Math.abs((candleReferencePrice-mainReferencePrice)/mainReferencePrice)*100:null;
 const referenceAligned=referenceGapPct!==null&&referenceGapPct<0.01;
 const candleLatestKind=candles?.latest_bar_kind||'period_close';
 const candleLatestLabel=candleLatestKind==='reference_quote'?'当前参考报价':candleLatestKind==='reference_quote_on_synthetic'?'当前参考价（合成K线）':candleLatestKind==='synthetic'?'演示K线收盘':`最近${candleIntervalLabel(candleEffectiveInterval)}收盘`;
 const candleCalibrationText=!candles?'等待主力参考价与 K 线同步':mainReferencePrice===null?'暂无可核验主力参考价；不使用静态旧值校准':candleLatestKind==='period_close'&&candleReferencePrice!==null?`口径不同：主力参考价 ${formatPrice(mainReferencePrice)}；${candleIntervalLabel(candleEffectiveInterval)}收盘 ${formatPrice(candleLastPrice)}，分别代表当前报价与周期收盘`:candleLatestKind==='synthetic'?'演示/合成数据：不参与实盘校准':candleLatestKind==='reference_quote_on_synthetic'?'当前参考价已对齐，但 OHLC 仍为合成占位，不参与实盘校准':referenceGapPct!==null&&!referenceAligned?`需复核：主力参考价与 K 线参考价相差 ${referenceGapPct.toFixed(3)}%`:`已校准：主力参考价与 K 线当前报价一致（偏差 ${referenceGapPct===null?'—':referenceGapPct.toFixed(3)}%）`;
 const candleCalibrationClass=!candles||mainReferencePrice===null||['synthetic','reference_quote_on_synthetic'].includes(candleLatestKind)?'pending':candleLatestKind==='period_close'?'period':referenceAligned?'aligned':'warning';
 const uploadStatusText=(item:ImageMeta)=>item.status==='reading'?'读取中':item.status==='analyzing'?'分析中':item.status==='done'?'已完成':item.status==='error'?'失败':item.status==='ready'?'待提交':'已加入';
